(function(){
var D=window.AT,rows=D.rows,st={q:'',basis:'box',sort:'best5',dir:-1,dec:'',act:false,minq:3,lim:250};
var M='−';function $(s){return document.querySelector(s)}
function norm(s){return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase()}
rows.forEach(function(r){r._n=norm(r.name)});
function v(r,k){if(k==='name')return r._n;if(k==='first'||k==='gp'||k==='min'||k==='q_seasons')return r[k];var b=st.basis==='box'?r.box:r;return b?b[k]:null}
function f1(x){if(x==null)return'–';var s=Math.abs(x).toFixed(1);return(x<0&&+s?M:(+s?'+':''))+s}
function pass(r){if(st.q&&r._n.indexOf(norm(st.q))<0)return false;if(st.act&&!r.active)return false;
 if(st.dec&&Math.floor(r.first/10)*10!=+st.dec)return false;if(!st.q&&(r.q_seasons||0)<st.minq)return false;return true}
function sl(y){return y+'-'+String(y+1).slice(2)}
function render(){var L=rows.filter(pass);var k=st.sort;
 L.sort(function(a,b){var x=v(a,k),y=v(b,k);if(x==null&&y==null)return a._n<b._n?-1:1;if(x==null)return 1;if(y==null)return-1;
  if(typeof x==='string')return x.localeCompare(y)*st.dir;return(x-y)*st.dir||(a._n<b._n?-1:1)});
 var out=[];for(var i=0;i<Math.min(L.length,st.lim);i++){var r=L[i],b=st.basis==='box'?r.box:r;
  out.push('<tr><td class="rk">'+(i+1)+'</td><td class="nm l stk"><a href="/singular/p/'+r.slug+'/">'+r.name.replace(/</g,'&lt;')+'</a>'+(r.active?' <small class="act">active</small>':'')+'</td>'+
  '<td class="l">'+sl(r.first)+' to '+sl(r.last)+'</td><td>'+(r.q_seasons||0)+'</td><td>'+r.gp.toLocaleString()+'</td>'+
  '<td class="kc sep">'+f1(b&&b.best5)+'</td><td>'+f1(b&&b.best3)+'</td><td>'+f1(b&&b.best)+'</td><td class="l">'+(b&&b.best_season?sl(b.best_season):'–')+'</td><td>'+f1(b&&b.career)+'</td></tr>')}
 $('#at tbody').innerHTML=out.join('')||'<tr><td colspan="10" class="empty l">No players match.</td></tr>';
 $('#count').textContent=L.length.toLocaleString()+' players'+(L.length>st.lim?' (showing '+st.lim+')':'');
 $('#more').hidden=L.length<=st.lim;
 document.querySelectorAll('[data-basis]').forEach(function(x){x.setAttribute('aria-pressed',x.dataset.basis===st.basis)});
 document.querySelectorAll('#at thead [data-k]').forEach(function(x){x.closest('th').setAttribute('aria-sort',x.dataset.k===st.sort?(st.dir<0?'descending':'ascending'):'none')})}
document.addEventListener('DOMContentLoaded',function(){
 var q=new URLSearchParams(location.search).get('q');if(q){st.q=q;$('#q').value=q}
 $('#q').addEventListener('input',function(e){st.q=e.target.value;st.lim=250;render()});
 $('#dec').addEventListener('change',function(e){st.dec=e.target.value;render()});
 $('#act').addEventListener('change',function(e){st.act=e.target.checked;render()});
 $('#minq').addEventListener('change',function(e){st.minq=+e.target.value;render()});
 $('#more').addEventListener('click',function(){st.lim+=500;render()});
 document.addEventListener('click',function(e){var b=e.target.closest('[data-basis]');if(b){st.basis=b.dataset.basis;render();return}
  var h=e.target.closest('#at thead [data-k]');if(h){var k=h.dataset.k;if(st.sort===k)st.dir=-st.dir;else{st.sort=k;st.dir=(k==='name'||k==='first')?1:-1}render()}});
 render()});
})();